import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import { istDateStr } from "../_shared/ist_date.ts";
import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
import { logCronEnd, logCronStart } from "../_shared/cron_telemetry.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

interface WorkoutLog {
  user_id: string;
  exercise_id: string;
  exercise_name: string;
  weight_kg: number | null;
  reps: number | null;
  completed_at: string;
  date: string; // derived from completed_at
}

interface ScheduledWorkout {
  user_id: string;
  status: string;
  scheduled_date: string;
}

/**
 * Calculates experience level based on 4 weeks of workout data.
 *
 * Scoring:
 * - Weight progression: Did they increase weight on key exercises? (0-25)
 * - Completion rate: Workouts done / planned (0-25)
 * - Exercise variety: Unique exercises used (0-25)
 * - Consistency: How many of the 4 weeks had at least 1 workout (0-25)
 *
 * Total: 0-100
 * beginner: 0-39, intermediate: 40-69, advanced: 70-100
 */
function calculateExperienceLevel(
  logs: WorkoutLog[],
  scheduled: ScheduledWorkout[],
): string {
  if (logs.length === 0) return "beginner";

  // --- Weight Progression Score (0-25) ---
  // Group logs by exercise, check if weight increased over the 4 weeks
  const exerciseWeights: Record<string, { date: string; weight: number }[]> = {};
  for (const log of logs) {
    if (log.weight_kg && log.weight_kg > 0) {
      const key = log.exercise_id ?? log.exercise_name;
      if (!exerciseWeights[key]) exerciseWeights[key] = [];
      exerciseWeights[key].push({ date: log.date, weight: log.weight_kg });
    }
  }

  let progressingExercises = 0;
  let totalWeightedExercises = 0;
  for (const entries of Object.values(exerciseWeights)) {
    if (entries.length < 2) continue;
    totalWeightedExercises++;
    const sorted = entries.sort(
      (a, b) => new Date(a.date).getTime() - new Date(b.date).getTime(),
    );
    const firstWeight = sorted[0].weight;
    const lastWeight = sorted[sorted.length - 1].weight;
    if (lastWeight > firstWeight) progressingExercises++;
  }

  const progressionScore =
    totalWeightedExercises > 0
      ? Math.round((progressingExercises / totalWeightedExercises) * 25)
      : 0;

  // --- Completion Rate Score (0-25) ---
  const totalPlanned = scheduled.length || 1;
  const totalCompleted = scheduled.filter((s) => s.status === "completed").length;
  const completionScore = Math.round(
    Math.min(totalCompleted / totalPlanned, 1) * 25,
  );

  // --- Exercise Variety Score (0-25) ---
  const uniqueExercises = new Set(
    logs.map((l) => l.exercise_id ?? l.exercise_name),
  );
  // 15+ unique exercises in 4 weeks = max score
  const varietyScore = Math.round(Math.min(uniqueExercises.size / 15, 1) * 25);

  // --- Consistency Score (0-25) ---
  // How many of the 4 weeks had at least 1 workout logged
  const weeksWithWorkouts = new Set<number>();
  const now = new Date();
  for (const log of logs) {
    const logDate = new Date(log.date);
    const weekNum = Math.floor(
      (now.getTime() - logDate.getTime()) / (7 * 24 * 60 * 60 * 1000),
    );
    if (weekNum >= 0 && weekNum < 4) weeksWithWorkouts.add(weekNum);
  }
  const consistencyScore = Math.round((weeksWithWorkouts.size / 4) * 25);

  const totalScore =
    progressionScore + completionScore + varietyScore + consistencyScore;

  if (totalScore >= 70) return "advanced";
  if (totalScore >= 40) return "intermediate";
  return "beginner";
}

/**
 * Fetches all rows from a table with pagination to handle large datasets.
 * Supabase JS client returns max 1000 rows by default; this fetches all pages.
 */
async function fetchAllRows<T>(
  supabaseClient: SupabaseClient,
  table: string,
  selectCols: string,
  dateColumn: string,
  dateGte: string,
): Promise<T[]> {
  const PAGE_SIZE = 1000;
  const allRows: T[] = [];
  let offset = 0;
  let hasMore = true;

  while (hasMore) {
    const { data, error } = await supabaseClient
      .from(table)
      .select(selectCols)
      .gte(dateColumn, dateGte)
      .range(offset, offset + PAGE_SIZE - 1);

    if (error) {
      throw new Error(`Failed to fetch ${table} at offset ${offset}: ${error.message}`);
    }

    if (data && data.length > 0) {
      allRows.push(...(data as T[]));
      offset += data.length;
      // If we got fewer rows than PAGE_SIZE, we've reached the end
      hasMore = data.length === PAGE_SIZE;
    } else {
      hasMore = false;
    }
  }

  return allRows;
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  // ── Auth gate added 2026-07-26 (diagnose c3f8a1, Hermes L23/L24).
  //
  // This function shipped verify_jwt=false with NO authentication of any kind
  // while creating a SERVICE-ROLE client below — so any unauthenticated POST
  // from anywhere on the internet could drive a full-fleet recalculation over
  // every user. It escaped every guard because it is scheduled by nothing (zero
  // cron.job rows) and its client constant `weeklyRecalcFunction` is declared
  // but never invoked, so neither the cron registry nor any call-site grep saw
  // it — while `cron_auth_adoption_test.dart` omitted it and
  // `cron_telemetry_adoption_test.dart` listed it, the two hand-maintained
  // lists disagreeing about what it even is.
  //
  // Exactly the F44 shape: an unguarded verify_jwt=false service-role endpoint
  // invisible because no list covered it.
  if (!await isAuthorizedCronCall(req)) {
    console.warn(`[weekly-recalc] unauthorized caller; status=401`);
    return new Response(
      JSON.stringify({ error: "Unauthorized" }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  // OI-21 / audit-2026-05-29 EF-2: in-function execution telemetry so the
  // alert_edge_function_health cron (migrations 076/077) can SEE weekly-recalc
  // failures via cron_call_log. pg_cron's job_run_details only reflects the
  // net.http_post dispatch, not the EF's actual HTTP outcome.
  //
  // Placed AFTER the gate above — before it, an anonymous caller would get an
  // unauthenticated INSERT into public.cron_call_log (see _shared/cron_auth.ts).
  const logId = await logCronStart("weekly-recalc");

  try {
    const start = Date.now();

    // Cron-shaped job: service-role client, authorized by the CRON_SECRET gate
    // above rather than by a caller JWT.
    const supabaseClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // audit-2026-05-11 H-8 — 4-week window now IST-anchored so the
    // weekly recalc covers IST weeks not UTC weeks (5h30m drift
    // would mis-align with the user's actual training calendar).
    const fourWeeksAgo = new Date();
    fourWeeksAgo.setDate(fourWeeksAgo.getDate() - 28);
    const fourWeeksAgoStr = istDateStr(fourWeeksAgo);

    // ── STEP 1: Bulk fetch ALL data in 2 parallel queries ──
    // Read from workout_log_exercises (per-exercise data) instead of workout_logs
    // (which now stores summary rows after sync refactor).
    const [rawLogs, allScheduled] = await Promise.all([
      fetchAllRows<{ user_id: string; exercise_id: string; exercise_name: string; weight_kg: number | null; reps: number | null; completed_at: string }>(
        supabaseClient,
        "workout_log_exercises",
        "user_id, exercise_id, exercise_name, weight_kg, reps, completed_at",
        "completed_at",
        fourWeeksAgoStr + "T00:00:00Z",
      ),
      fetchAllRows<ScheduledWorkout>(
        supabaseClient,
        "scheduled_workouts",
        "user_id, status, scheduled_date",
        "scheduled_date",
        fourWeeksAgoStr,
      ),
    ]);

    // Derive date from completed_at for downstream scoring
    const allLogs: WorkoutLog[] = rawLogs.map((r) => ({
      ...r,
      date: r.completed_at ? r.completed_at.split("T")[0] : fourWeeksAgoStr,
    }));

    console.log(
      `weekly-recalc: fetched ${allLogs.length} logs, ${allScheduled.length} scheduled in ${Date.now() - start}ms`,
    );

    // ── STEP 2: Group by user_id in JavaScript ──
    const logsByUser = new Map<string, WorkoutLog[]>();
    for (const log of allLogs) {
      const list = logsByUser.get(log.user_id);
      if (list) {
        list.push(log);
      } else {
        logsByUser.set(log.user_id, [log]);
      }
    }

    const scheduledByUser = new Map<string, ScheduledWorkout[]>();
    for (const sw of allScheduled) {
      const list = scheduledByUser.get(sw.user_id);
      if (list) {
        list.push(sw);
      } else {
        scheduledByUser.set(sw.user_id, [sw]);
      }
    }

    // Merge all user IDs from both maps (a user might have logs but no schedule, or vice versa)
    const allUserIds = new Set<string>([
      ...logsByUser.keys(),
      ...scheduledByUser.keys(),
    ]);

    console.log(
      `weekly-recalc: grouped data for ${allUserIds.size} users in ${Date.now() - start}ms`,
    );

    // ── STEP 3: Calculate experience level for each user locally ──
    const levels = new Map<string, string>();
    const workoutCounts = new Map<string, number>();

    for (const userId of allUserIds) {
      const userLogs = logsByUser.get(userId) || [];
      const userScheduled = scheduledByUser.get(userId) || [];

      const level = calculateExperienceLevel(userLogs, userScheduled);
      levels.set(userId, level);
      // Count distinct workout dates, not exercise rows.
      // Each row is a per-exercise summary; a 6-exercise workout = 6 rows but 1 workout.
      const distinctDates = new Set(userLogs.map((l) => l.date));
      workoutCounts.set(userId, distinctDates.size);
    }

    console.log(
      `weekly-recalc: calculated levels for ${levels.size} users in ${Date.now() - start}ms`,
    );

    // ── STEP 4: Batch UPDATE in chunks of 100 concurrent upserts ──
    const BATCH_SIZE = 100;
    const userIds = Array.from(allUserIds);
    let processed = 0;
    let errors = 0;
    const nowIso = new Date().toISOString();

    // Diagnose 3a7b9f (2026-05-27, c2 audit finding): `total_workouts_done`
    // is a LIFETIME monotonic counter incremented by client at workout
    // completion (train_provider.dart:1420). Pre-fix this cron overwrote
    // it with the count of distinct dates from the LAST 4 WEEKS of
    // workout_log_exercises (recompute window at line 174-176 + line 251).
    // For any user who trained more than 4 weeks ago, the recalc would
    // silently DECREASE their lifetime counter every Sunday. Defense:
    // pre-fetch existing values and apply GREATEST in the upsert payload.
    // Same monotonic-field-recompute class as the rank demotion fix.
    const existingProgress = new Map<string, number>();
    for (let i = 0; i < userIds.length; i += BATCH_SIZE) {
      const chunk = userIds.slice(i, i + BATCH_SIZE);
      const { data: rows } = await supabaseClient
        .from("user_progress")
        .select("user_id, total_workouts_done")
        .in("user_id", chunk);
      for (const row of (rows ?? []) as Array<Record<string, unknown>>) {
        existingProgress.set(
          row.user_id as string,
          (row.total_workouts_done as number | null) ?? 0,
        );
      }
    }

    for (let i = 0; i < userIds.length; i += BATCH_SIZE) {
      const chunk = userIds.slice(i, i + BATCH_SIZE);

      const results = await Promise.all(
        chunk.map((userId) => {
          const recomputed = workoutCounts.get(userId) || 0;
          const existing = existingProgress.get(userId) || 0;
          const monotonicTotal = Math.max(recomputed, existing);
          return supabaseClient
            .from("user_progress")
            .upsert(
              {
                user_id: userId,
                detected_experience_level: levels.get(userId),
                experience_last_calculated: nowIso,
                total_workouts_done: monotonicTotal,
              },
              { onConflict: "user_id" },
            )
            .then((res) => ({ userId, error: res.error }));
        }),
      );

      for (const result of results) {
        if (result.error) {
          console.error(
            `Failed to update experience for user ${result.userId}:`,
            result.error,
          );
          errors++;
        } else {
          processed++;
        }
      }
    }

    const totalTime = Date.now() - start;
    console.log(
      `weekly-recalc: processed ${processed} users, ${errors} errors in ${totalTime}ms`,
    );

    const status = errors === 0 ? "success" : (errors > processed ? "failed" : "partial");
    const httpStatus = errors > processed ? 500 : 200;
    await logCronEnd(logId, httpStatus >= 400 ? "failed" : "success", {
      httpStatus,
      errorSummary: errors > 0 ? `${errors} user-update errors` : undefined,
    });
    return new Response(
      JSON.stringify({
        status,
        users_processed: processed,
        errors,
        total_users: allUserIds.size,
        total_logs: allLogs.length,
        total_scheduled: allScheduled.length,
        duration_ms: totalTime,
      }),
      {
        status: httpStatus,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  } catch (err) {
    // Sanitised 5xx: never leak raw exception / SQL text.
    const requestId = crypto.randomUUID().split("-")[0];
    console.error(`[weekly-recalc] request_id=${requestId}`, err);
    await logCronEnd(logId, "failed", {
      httpStatus: 500,
      requestId,
      errorSummary: String(err),
    });
    return new Response(
      JSON.stringify({ error: "Internal server error", request_id: requestId }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  }
});

// supabase/functions/_shared/ist_date.ts
// IST (UTC+5:30) date helpers shared across Edge Functions.
// Mirrors lib/core/utils/ist_date.dart on the Flutter client so both sides
// agree on what "today" means.

export const IST_OFFSET_MS = (5 * 60 + 30) * 60 * 1000;

/// Returns a new Date object shifted to IST (UTC+5:30).
export function istNow(d: Date = new Date()): Date {
  return new Date(d.getTime() + IST_OFFSET_MS);
}

/// Returns 'YYYY-MM-DD' in IST.
export function istDateStr(d: Date = new Date()): string {
  const ist = istNow(d);
  return ist.toISOString().substring(0, 10);
}

/// Returns day-of-week in IST (Sun=0 .. Sat=6).
/// Mirrors JavaScript's getDay() but computed in IST, not the server's local TZ.
export function istDayOfWeek(d: Date = new Date()): number {
  return istNow(d).getUTCDay();
}

/// Returns IST midnight (00:00:00 IST) for the given date as a
/// timestamptz-comparable ISO string carrying the +05:30 offset.
/// Use this for cloud rate-limit / cap queries like
/// `.gte("created_at", istDayStartIso())` so the "today" window
/// aligns with the user's IST day instead of UTC midnight (a 5h30m
/// drift that gives Indian users a stale rate-limit reset at
/// 05:30 IST every morning).
///
/// audit-2026-05-11 H-4 / H-10 — ai-proxy + ai-media-proxy vision
/// caps + free-tier message count were filtering against UTC
/// midnight; switched to this helper.
export function istDayStartIso(d: Date = new Date()): string {
  return `${istDateStr(d)}T00:00:00+05:30`;
}

/**
 * cron_auth.ts — shared-secret auth gate for cron-dispatched Edge Functions.
 *
 * Rewritten 2026-07-26 (closes-diagnose: c3f8a1). See HISTORY at the bottom —
 * the two previous designs both failed in production, and the second failed
 * silently for roughly eight weeks.
 *
 * AUTH MODEL
 * ----------
 * A single opaque shared secret. The caller must present
 * `Authorization: Bearer <CRON_SECRET>`, where `CRON_SECRET` is an Edge
 * Function secret whose value also lives in the Vault row `cron_secret`, read
 * by `private.cron_get_secret()` and interpolated into every `cron.job`
 * command (migrations 107/108).
 *
 * WHY A SHARED SECRET RATHER THAN A JWT
 * -------------------------------------
 * This is machine-to-machine auth between pg_cron and the Edge runtime. There
 * is no user identity to carry, no claims to inspect and no delegation — a
 * signed token buys nothing here, and every JWT-shaped attempt has coupled the
 * gate to platform key management that then changed underneath it:
 *
 *   - Attempt 1 compared the token to `SUPABASE_SERVICE_ROLE_KEY`. Broke when
 *     the Vault copy and the env copy drifted (diagnose 5a65bd).
 *   - Attempt 2 verified the signature against `SUPABASE_JWT_SECRET` — a
 *     variable Supabase does not inject and **forbids creating**, because the
 *     platform reserves the `SUPABASE_` prefix for secret names. Unsatisfiable
 *     by construction; every cron call 401'd from the day it deployed.
 *
 * A string comparison has no such coupling. It is unaffected by the JWT
 * signing-key migration now underway on this project and by the deprecation of
 * `SUPABASE_ANON_KEY` / `SUPABASE_SERVICE_ROLE_KEY`.
 *
 * ⚠ THE SECRET IS THE ONLY GATE. Cron functions run `verify_jwt=false`, so
 * their URLs accept unauthenticated POSTs from anywhere and this comparison is
 * all that stands between the open internet and a privileged fan-out (push
 * sends, Gemini spend, storage deletion). `CRON_SECRET` must be long and
 * cryptographically random — `openssl rand -hex 32`. Never a memorable phrase.
 *
 * USAGE (per cron function)
 * -------------------------
 *   import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
 *
 *   Deno.serve(async (req) => {
 *     if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
 *     if (!await isAuthorizedCronCall(req)) {
 *       return new Response(JSON.stringify({ error: "Unauthorized" }), {
 *         status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 *       });
 *     }
 *     const logId = await logCronStart("<slug>");   // AFTER the gate — see below
 *     // ... handler body
 *   });
 *
 * ⚠ KEEP `logCronStart` AFTER THIS GATE. It is tempting to move it earlier so
 * that rejected calls leave a telemetry row — the 2026-07-26 batch considered
 * exactly that. Don't: on a `verify_jwt=false` endpoint it would hand every
 * anonymous caller an unauthenticated INSERT into `public.cron_call_log`.
 * Outage visibility is provided instead by `alert_cron_silence` (migration
 * 109), which alerts on the ABSENCE of successful runs and therefore needs no
 * writes from unauthenticated callers.
 */

/**
 * Constant-time string comparison.
 *
 * Both sides are hashed to a fixed 32-byte digest first, then compared with an
 * XOR-accumulate that always walks the full length. This leaks neither the
 * secret's length nor the position of the first differing byte, whereas a plain
 * `!==` short-circuits on the first mismatch and is measurable over enough
 * requests.
 *
 * Worth the few microseconds here specifically because this comparison is the
 * ONLY gate on 16 publicly-reachable endpoints (see the warning above), and the
 * secret in production is currently low-entropy by explicit accepted risk
 * (migration 107 header) — a weak secret plus a timing oracle is materially
 * worse than either alone.
 */
async function timingSafeEqual(a: string, b: string): Promise<boolean> {
  const enc = new TextEncoder();
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", enc.encode(a)),
    crypto.subtle.digest("SHA-256", enc.encode(b)),
  ]);
  const va = new Uint8Array(da);
  const vb = new Uint8Array(db);
  let diff = 0;
  for (let i = 0; i < va.length; i++) diff |= va[i] ^ vb[i];
  return diff === 0;
}

/**
 * True when the request carries `Authorization: Bearer <CRON_SECRET>`.
 *
 * False on a missing header, a malformed bearer, an unset `CRON_SECRET`, or any
 * mismatch. Never throws — safe to call without try/catch.
 */
export async function isAuthorizedCronCall(req: Request): Promise<boolean> {
  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    if (!authHeader.startsWith("Bearer ")) {
      console.warn("[cron_auth] missing or malformed Authorization header");
      return false;
    }
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length === 0) {
      console.warn("[cron_auth] empty bearer token");
      return false;
    }

    // Trimmed on BOTH sides. A trailing newline pasted into the dashboard
    // secret would otherwise reject every call with no visible reason.
    const cronSecret = (Deno.env.get("CRON_SECRET") ?? "").trim();
    if (cronSecret.length === 0) {
      console.warn(
        "[cron_auth] CRON_SECRET is unset — every cron call will be rejected. " +
          "Set it in Project Settings -> Edge Functions -> Secrets, matching " +
          "the `cron_secret` Vault row exactly.",
      );
      return false;
    }

    if (!await timingSafeEqual(token, cronSecret)) {
      console.warn("[cron_auth] bearer token does not match CRON_SECRET");
      return false;
    }

    return true;
  } catch (err) {
    // Defensive — never let the auth gate crash its caller.
    console.error("[cron_auth] unexpected error:", err);
    return false;
  }
}

/*
 * HISTORY
 * -------
 * 2026-05-11 (7ad0c4)  Gate introduced; 8 cron functions were publicly callable.
 * 2026-05-12 (audit P0) Vault `service_role_key` row was empty, so the header
 *                       went out as `Bearer null` → 401 on every tick, 12 jobs.
 * 2026-05-15 (5a65bd)  Env-equality check broke on Vault/env key drift. That
 *                       write-up proposed "replace the brittle env-equality
 *                       check with a JWT signature+role decode" as the
 *                       permanent class fix.
 * 2026-05-16           The class fix shipped. It depended on
 *                       `SUPABASE_JWT_SECRET`, which cannot exist. The fix
 *                       made the bug permanent instead of ending it.
 * 2026-07-26 (c3f8a1)  Discovered: ~8 weeks of total cron silence. Three
 *                       safeguards had failed together — telemetry sat behind
 *                       the failing gate, pg_cron reports `succeeded` for any
 *                       dispatch regardless of HTTP status, and the health
 *                       alert computed a rate from the table the failure kept
 *                       empty. Replaced with this shared-secret gate; the
 *                       `deno.land/x/jose` dependency is gone with it, closing
 *                       a remote-dep-rot risk this repo has already been bitten
 *                       by (feedback_mistake_remote_dep_rot).
 */

/**
 * cron_telemetry — per-invocation execution telemetry for cron Edge Functions.
 *
 * Closes audit 2026-05-17 / OI-15. Background: `cron.job_run_details.status='succeeded'`
 * only confirms the pg_cron-side `net.http_post()` dispatch succeeded; it does NOT
 * reflect the Edge Function's actual HTTP response. During the Vault drift incident
 * (2026-05-11..16, CLAUDE.md §19 entry "pr-detection cron loops 401 every 15 min"),
 * pg_cron reported 1066 "succeeded" runs across a week while every single call returned
 * 401 server-side and zero work happened.
 *
 * Each cron Edge Function imports this helper and:
 *   1. Calls `logCronStart(name)` at the top of its `serve` handler → returns a row id.
 *   2. Calls `logCronEnd(id, status, httpStatus?, errorSummary?)` before returning.
 *
 * The row lands in `public.cron_call_log` (migration 068). Retention: 7 days via
 * `public.cleanup_cron_call_log()` (must be wired by founder via pg_cron registration
 * — currently not scheduled; see open_issues.md OI-15 follow-up).
 *
 * Failures inside the telemetry call itself are SWALLOWED (try/catch + debug log).
 * Cron functions MUST NOT 500 because telemetry is broken.
 */

import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

type CronLogStatus = "success" | "failed";

let _adminClient: SupabaseClient | null = null;

function adminClient() {
  if (_adminClient) return _adminClient;
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    // Edge runtime quirk — should never happen in prod, but don't crash if it does.
    return null;
  }
  _adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
  return _adminClient;
}

/**
 * Insert a `started` row. Returns the row id so the caller can update on exit.
 *
 * Returns `null` if telemetry insert fails — callers should pass that null straight
 * back into `logCronEnd` (which is a no-op on null id). The function itself never
 * throws.
 */
export async function logCronStart(functionName: string): Promise<number | null> {
  try {
    const supabase = adminClient();
    if (!supabase) return null;
    const { data, error } = await supabase
      .from("cron_call_log")
      .insert({ function_name: functionName, status: "started" })
      .select("id")
      .single();
    if (error || !data) {
      console.warn(`[cron_telemetry] start insert failed for ${functionName}`, error);
      return null;
    }
    return (data as { id: number }).id;
  } catch (e) {
    console.warn(`[cron_telemetry] start exception for ${functionName}`, e);
    return null;
  }
}

/**
 * Update the row created by `logCronStart` with terminal status.
 *
 * Passes-through silently when `id` is null (i.e. start insert failed).
 */
export async function logCronEnd(
  id: number | null,
  status: CronLogStatus,
  opts?: { httpStatus?: number; requestId?: string; errorSummary?: string },
): Promise<void> {
  if (id == null) return;
  try {
    const supabase = adminClient();
    if (!supabase) return;
    const patch: Record<string, unknown> = { status };
    if (opts?.httpStatus !== undefined) patch.http_status = opts.httpStatus;
    if (opts?.requestId) patch.request_id = opts.requestId;
    if (opts?.errorSummary) {
      // Cap error summary at 1000 chars to avoid bloat from giant stack traces.
      patch.error_summary = opts.errorSummary.slice(0, 1000);
    }
    const { error } = await supabase
      .from("cron_call_log")
      .update(patch)
      .eq("id", id);
    if (error) {
      console.warn(`[cron_telemetry] end update failed for id=${id}`, error);
    }
  } catch (e) {
    console.warn(`[cron_telemetry] end exception for id=${id}`, e);
  }
}
